+/** Theoretical use from sales vs actual consume movements between two days (inclusive). */
+export function varianceReport(store, from, to) {
+  const theoreticalByItem = new Map();
+  const dishes = new Map((store.data.dishes ?? []).map((d) => [d.id, d]));
+  const recipes = new Map(store.data.recipes.map((r) => [r.id, r]));
+  for (const sale of store.data.sales ?? []) {
+    const day = dayOf(sale.soldAt);
+    if (day < from || day > to) continue;
+    const dish = dishes.get(sale.dishId);
+    const recipe = dish ? recipes.get(dish.recipeId) : null;
+    if (!recipe) continue;
+    for (const n of scaled(recipe, sale.qty)) {
+      theoreticalByItem.set(n.itemId, (theoreticalByItem.get(n.itemId) ?? 0) + n.qty);
+    }
+  }
+
+  const actualByItem = new Map();
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId === undefined) continue;
+    actualByItem.set(itemId, (actualByItem.get(itemId) ?? 0) + m.qty);
+  }
+
+  const lines = [];
+  for (const item of listItems(store)) {
+    const theoretical = Math.round((theoreticalByItem.get(item.id) ?? 0) * 1000) / 1000;
+    const actual = Math.round((actualByItem.get(item.id) ?? 0) * 1000) / 1000;
+    if (theoretical <= 0 && actual <= 0) continue;
+    lines.push({
+      itemId: item.id,
+      name: item.name,
+      theoretical,
+      actual,
+      diff: Math.round((actual - theoretical) * 1000) / 1000,
+    });
+  }
+  return lines;
+}
